namespace ghidra.features.bsim.query.protocol;




using generic.lsh.vector;
using ghidra.features.bsim.query;
using ghidra.util.xml;
using ghidra.xml;
using ghidra.xml;

/**
 * Request that a BSim database either drop or build its main vector index
 *
 */
public class AdjustVectorIndex : BSimQuery<ResponseAdjustIndex> {

	public bool doRebuild;			// true if vector index should be rebuilt, false if it should be dropped
	public ResponseAdjustIndex adjustresponse;
	
	public AdjustVectorIndex() : base("adjustindex")
    {
		doRebuild = false;
	}
	
	/* (non-Javadoc)
	 * @see ghidra.query.protocol.QueryResponseRecord#buildResponseTemplate()
	 */
	/* @Override */
	public void buildResponseTemplate() {
		if (response == null)
			response = adjustresponse = new ResponseAdjustIndex();
	}
	
	/* @Override */
	public void saveXml(Writer fwrite)
    {
		fwrite.append('<').append(name);
		fwrite.append(" rebuild=\"");
		fwrite.append(SpecXmlUtils.encodeBoolean(doRebuild));
		fwrite.append("\"/>\n");
	}

	/* @Override */
	public void restoreXml(XmlPullParser parser, LSHVectorFactory vectorFactory)
    {
		XmlElement el = parser.start(name);
		doRebuild = SpecXmlUtils.decodeBoolean(el.getAttribute("rebuild"));
		parser.end();
	}

}
